'use server'

import { refresh } from 'next/cache'
import {
  getNotificationsEnabled,
  setNotificationsEnabled,
} from '@/lib/preferences'

// Replace with your real auth/session lookup. Never trust a user ID sent from the client.
async function getCurrentUserId(): Promise<string> {
  return 'demo-user'
}

export async function toggleNotifications(): Promise<void> {
  const userId = await getCurrentUserId()

  const current = await getNotificationsEnabled(userId)
  await setNotificationsEnabled(userId, !current)

  // Re-render the current route and send the fresh RSC payload back
  // in the same response, without navigating away.
  refresh()
}

