import { toggleNotifications } from './actions'
import { getNotificationsEnabled } from '@/lib/preferences'

export default async function Home() {
  // Replace with your real auth/session lookup.
  const enabled = await getNotificationsEnabled('demo-user')

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are <strong>{enabled ? 'on' : 'off'}</strong>.
      </p>
      <form action={toggleNotifications}>
        <button type="submit">
          {enabled ? 'Turn notifications off' : 'Turn notifications on'}
        </button>
      </form>
    </main>
  )
}

